"""Build a portable visual review from actual, unaltered browser captures."""
from pathlib import Path
import base64,html,json,shutil,sys
root=Path(__file__).resolve().parent.parent
run=root/'verification/next-build/cleanup-review-final-05'
out=root/'verification/cleanup-2026-10-17/visual-review'
(out/'captures').mkdir(parents=True,exist_ok=True)
report=json.loads((run/'report.json').read_text())
if report['summary']['failed'] or report['summary']['runtimeErrors']:raise SystemExit('Review capture run must pass')
pages={'dashboard':'Home','MSFT-Overview':'Stock overview','MSFT-Technicals':'Technicals','MSFT-Financials':'Financials','MSFT-Valuation':'Valuation','MSFT-Business':'Business','MSFT-Earnings-events':'Events','MSFT-Ownership':'Ownership','MSFT-Risks':'Risks','MSFT-Options':'Options','portfolio':'Portfolio','watchlist':'Saved','analyze':'Search','discover':'Discover','alerts':'Alerts','personalization':'Settings','profile':'Account','research-lab':'Research lab','trading-lab':'Trading lab','faq':'Help','login':'Login','onboarding':'Onboarding'}
items=[]
for theme in ['dark','light']:
 for width in [1440,390]:
  for slug,label in pages.items():
   name=f'{theme}-{width}-{slug}.png';p=run/'screenshots'/name
   if not p.exists():raise SystemExit('Capture missing: '+name)
   shutil.copy2(p,out/'captures'/name)
   items.append({'page':label,'theme':theme,'device':'Desktop' if width==1440 else 'Mobile','src':'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode(),'name':name})
header='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AURYN — Product Review</title><style>
*{box-sizing:border-box}body{margin:0;background:#071224;color:#eff5ff;font:15px/1.6 system-ui}header{max-width:1220px;margin:auto;padding:36px 24px 20px}h1{margin:0;font-size:32px;letter-spacing:-1px}p{color:#aebfdf;max-width:1000px}nav{position:sticky;top:0;z-index:10;background:#10213bf5;backdrop-filter:blur(14px);padding:14px 24px;border-block:1px solid #294063;display:flex;gap:18px;align-items:center;flex-wrap:wrap}label{display:flex;gap:8px;align-items:center;color:#b9c8e2;font-size:13px}select{font:inherit;min-height:42px;border:1px solid #375478;border-radius:8px;background:#152b49;color:white;padding:8px 12px}main{padding:24px;max-width:1500px;margin:auto}figure{margin:0 auto;max-width:1440px}figure.mobile{max-width:390px}img{display:block;width:100%;height:auto;border:1px solid #294063;border-radius:12px}figcaption{color:#aebfdf;font-size:12px;margin:14px 0}a{color:#9cbdff}button{cursor:pointer;background:#2459e7;color:white;font:inherit;border:0;border-radius:8px;padding:10px 16px}strong{color:#e8f0ff}.status{font-size:12px;color:#67e5c9;letter-spacing:1px}small{color:#aebfdf}details{max-width:1000px}summary{cursor:pointer}footer{padding:28px;text-align:center;color:#96aac9;font-size:12px}@media(max-width:600px){header{padding:24px 16px}main{padding:14px}nav{gap:10px;padding:10px 14px}label{flex-direction:column;align-items:flex-start;gap:2px}select{max-width:150px;font-size:16px}h1{font-size:26px}}
</style><header><div class="status">ACTUAL APPLICATION · REVIEW BEFORE DEPLOYMENT</div><h1>AURYN, simplified.</h1><p>Choose a screen, device and theme. These are captures of the production build, not generated mockups.</p><details><summary>Preview data and verification</summary><p>Quotes, investment assessments, account holdings, authentication and paper responses are synthetic test fixtures. Financial screens include previously retrieved company statements. None of these captures establishes current market data, investment performance or a live broker connection. This is a screenshot viewer; product actions are exercised in the browser test reports.</p><p>Full-page mobile images show the fixed bottom navigation at its original viewport position. The content scrolls behind it in the app. Physical iPhone/Safari verification is still pending.</p></details></header><nav><label>Screen<select id="page"></select></label><label>Device<select id="device"><option>Desktop</option><option>Mobile</option></select></label><label>Theme<select id="theme"><option value="dark">Dark</option><option value="light">Light</option></select></label><button id="next">Next screen →</button><small id="count"></small></nav><main><figure id="figure"><img id="capture" alt="Actual AURYN application screen"><figcaption id="caption"></figcaption></figure></main><footer>Production unchanged · Complete source and verification reports are included in the source ZIP.</footer>'''
script='''<script>const items=ITEMS;const pages=[...new Set(items.map(x=>x.page))];const $=id=>document.getElementById(id);pages.forEach(page=>{const o=document.createElement('option');o.textContent=page;$('page').append(o)});function render(){const item=items.find(x=>x.page===$('page').value&&x.device===$('device').value&&x.theme===$('theme').value);$('capture').src=item.src;$('capture').alt='Actual AURYN '+item.page+' · '+item.device+' · '+item.theme;$('figure').className=item.device==='Mobile'?'mobile':'';$('caption').textContent=item.page+' · '+item.device+' · '+item.theme+' · Preview data';$('count').textContent=(pages.indexOf(item.page)+1)+' / '+pages.length;}['page','device','theme'].forEach(id=>$(id).addEventListener('change',render));$('next').onclick=()=>{$('page').selectedIndex=($('page').selectedIndex+1)%pages.length;render();window.scrollTo({top:0,behavior:'smooth'})};render();</script></html>'''.replace('ITEMS',json.dumps(items))
portable=root.parent/'AURYN_Product_Review.html';portable.write_text(header+script)
# Source package contains a light, local-image version too.
local=[{**item,'src':'captures/'+item['name']} for item in items]
(out/'index.html').write_text(header+script.replace(json.dumps(items),json.dumps(local)))
(out/'README.md').write_text('# Actual AURYN review\n\nOpen index.html. All '+str(len(items))+' images are unaltered captures from '+run.relative_to(root).as_posix()+'. Quotes, assessments, account and paper data are fixtures; financial statements include saved provider evidence. No production deployment was made.\n')
print(json.dumps({'portable':str(portable),'screens':len(items),'build':report.get('release',{}).get('.next/BUILD_ID'),'bytes':portable.stat().st_size}))
